-- Monitor de Promoções de Hardware - MVP 1
-- Script para Oracle XE 18c ou superior (usa colunas IDENTITY).
-- Para a migração do MVP 2 (MySQL ou PostgreSQL), os ajustes principais são:
--   VARCHAR2 -> VARCHAR | NUMBER(1) -> BOOLEAN (PostgreSQL) ou TINYINT(1) (MySQL)
--   GENERATED BY DEFAULT AS IDENTITY -> AUTO_INCREMENT (MySQL) ou GENERATED BY DEFAULT AS IDENTITY (PostgreSQL)

CREATE TABLE LOJA (
    ID                    NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    NOME                  VARCHAR2(60)  NOT NULL UNIQUE,
    URL_BASE              VARCHAR2(200) NOT NULL,
    MODELO_LINK_AFILIADO  VARCHAR2(500),                  -- como o programa monta o link (definir quando aprovado)
    ATIVA                 NUMBER(1) DEFAULT 1 NOT NULL CHECK (ATIVA IN (0, 1)),
    CRIADO_EM             TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE PRODUTO (
    ID              NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    LOJA_ID         NUMBER NOT NULL REFERENCES LOJA (ID),
    CODIGO_LOJA     VARCHAR2(100)  NOT NULL,              -- identificador do produto na loja
    NOME            VARCHAR2(300)  NOT NULL,
    CATEGORIA       VARCHAR2(30)   NOT NULL,              -- GPU, SSD, RAM, CPU...
    URL_ORIGINAL    VARCHAR2(1000) NOT NULL,
    URL_AFILIADO    VARCHAR2(1500),
    IMAGEM_URL      VARCHAR2(1000),
    PRECO_ATUAL     NUMBER(10, 2),
    PRECO_ORIGINAL  NUMBER(10, 2),
    DISPONIVEL      NUMBER(1) DEFAULT 1 NOT NULL CHECK (DISPONIVEL IN (0, 1)),
    VISTO_EM        TIMESTAMP,                            -- última coleta em que o produto apareceu
    CRIADO_EM       TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    ATUALIZADO_EM   TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PROMOCAO_DESDE  TIMESTAMP,
    CONSTRAINT UQ_PRODUTO_LOJA_CODIGO UNIQUE (LOJA_ID, CODIGO_LOJA)
);

-- Só recebe registro quando o preço muda (RF2).
CREATE TABLE HISTORICO_PRECO (
    ID              NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    PRODUTO_ID      NUMBER NOT NULL REFERENCES PRODUTO (ID),
    PRECO           NUMBER(10, 2) NOT NULL,
    PRECO_ORIGINAL  NUMBER(10, 2),
    COLETADO_EM     TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE INDEX IDX_HISTORICO_PRODUTO_DATA ON HISTORICO_PRECO (PRODUTO_ID, COLETADO_EM);

-- Registro de eventos da coleta; alimenta o painel de monitoramento.
CREATE TABLE LOG_COLETA (
    ID          NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    LOJA_ID     NUMBER NOT NULL REFERENCES LOJA (ID),
    PRODUTO_ID  NUMBER REFERENCES PRODUTO (ID),           -- vazio em eventos da loja inteira
    TIPO        VARCHAR2(20) NOT NULL CHECK (TIPO IN
                    ('COLETA_OK', 'COLETA_FALHA', 'PRODUTO_NOVO',
                     'PRECO_ALTERADO', 'ESGOTADO', 'VOLTOU_ESTOQUE')),
    MENSAGEM    VARCHAR2(500),
    CRIADO_EM   TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE INDEX IDX_LOG_LOJA_DATA ON LOG_COLETA (LOJA_ID, CRIADO_EM);

-- Login do painel de monitoramento. Guardar apenas o hash da senha, nunca a senha.
CREATE TABLE USUARIO (
    ID          NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    EMAIL       VARCHAR2(200) NOT NULL UNIQUE,
    SENHA_HASH  VARCHAR2(255) NOT NULL,
    CRIADO_EM   TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

-- Promoções ativas com o desconto calculado (o desconto não é guardado, é derivado).
CREATE OR REPLACE VIEW V_PROMOCOES_ATIVAS AS
SELECT p.ID,
       l.NOME AS LOJA,
       p.NOME,
       p.CATEGORIA,
       p.PRECO_ATUAL,
       p.PRECO_ORIGINAL,
       ROUND((1 - p.PRECO_ATUAL / p.PRECO_ORIGINAL) * 100) AS DESCONTO_PCT,
       p.URL_AFILIADO,
       p.IMAGEM_URL
FROM PRODUTO p
JOIN LOJA l ON l.ID = p.LOJA_ID
WHERE p.DISPONIVEL = 1
  AND p.PRECO_ORIGINAL > p.PRECO_ATUAL;

